-- Report:  RPT_062_ReplPackDiscontinued7Days
-- Module:  Replenishment
-- Source:  RPT_062_ReplPackDiscontinued7Days.dva
-- Generated by MFCS DVA SQL Extractor


-- ── Query 1 ────────────────────────────────────────────────────────────
SELECT     TRUNC(SYSDATE)                                        AS \"Report Date\",     TRUNC(SYSDATE) - TRUNC(pil.STATUS_UPDATE_DATE)       AS \"Days Since Discontinued\",      cim.DEPT                                              AS \"Department Number\",     d.DEPT_NAME                                           AS \"Department Name\",     cim.CLASS                                             AS \"Class Number\",     c.CLASS_NAME                                          AS \"Class Name\",     cim.SUBCLASS                                          AS \"Subclass Number\",     sc.SUB_NAME                                           AS \"Subclass Name\",      pi.ITEM                                               AS \"Consumer Item ID\",     cim.ITEM_DESC                                         AS \"Consumer Item Description\",     cim.STANDARD_UOM                                      AS \"Consumer Unit of Measure\",     cim.STATUS                                            AS \"Consumer Item Status\",      pim.ITEM                                              AS \"Pack Item ID\",     pim.ITEM_DESC                                         AS \"Pack Item Description\",     pim.PACK_IND                                          AS \"Pack Indicator\",     pi.PACK_QTY                                           AS \"Component Quantity in Pack\",      pil.STATUS                                            AS \"Pack Location Status\",     'Discontinued'                                        AS \"Pack Location Status Description\",     pil.STATUS_UPDATE_DATE                                AS \"Pack Discontinued Date\",      pil.LOC                                               AS \"Location ID\",     pil.LOC_TYPE                                          AS \"Location Type\",     CASE pil.LOC_TYPE         WHEN 'S' THEN 'Store'         WHEN 'W' THEN 'Warehouse'     END                                                   AS \"Location Type Description\",     CASE pil.LOC_TYPE         WHEN 'S' THEN st.STORE_NAME         WHEN 'W' THEN wh.WH_NAME     END                                                   AS \"Location Name\",      cil.STATUS                                            AS \"Consumer Location Status\",     CASE cil.STATUS         WHEN 'A' THEN 'Active'         WHEN 'C' THEN 'Discontinued'         WHEN 'I' THEN 'Inactive'         WHEN 'D' THEN 'Delete'     END                                                   AS \"Consumer Location Status Description\",      ril.REPL_METHOD                                       AS \"Replenishment Method\",     CASE ril.REPL_METHOD         WHEN 'C'  THEN 'Constant'         WHEN 'D'  THEN 'Dynamic'         WHEN 'F'  THEN 'Floating Point'         WHEN 'M'  THEN 'Min/Max'         WHEN 'T'  THEN 'Time Supply'         WHEN 'SO' THEN 'Store Orders'         WHEN 'DI' THEN 'Dynamic - Issues'         WHEN 'S'  THEN 'Dynamic - Seasonal'         WHEN 'TI' THEN 'Time Supply - Issues'         WHEN 'E'  THEN 'Time Supply - Seasonal'         ELSE ril.REPL_METHOD     END                                                   AS \"Replenishment Method Description\",     ril.STOCK_CAT                                         AS \"Stock Category\",     CASE ril.STOCK_CAT         WHEN 'C' THEN 'Cross-Docked'         WHEN 'D' THEN 'Direct to Store'         WHEN 'L' THEN 'WH/Cross Link'         WHEN 'W' THEN 'Warehouse Stocked'         WHEN 'X' THEN 'PO Cross-link'         ELSE ril.STOCK_CAT     END                                                   AS \"Stock Category Description\",     ril.REPL_ORDER_CTRL                                   AS \"Order Control\",     ril.MIN_STOCK                                         AS \"Minimum Stock\",     ril.MAX_STOCK                                         AS \"Maximum Stock\",      ril.PRIMARY_PACK_NO                                   AS \"Current Primary Replenishment Pack\",     CASE         WHEN ril.PRIMARY_PACK_NO IS NULL         THEN 'NO PACK CONFIGURED - ORDERING AT UNIT LEVEL'         WHEN ril.PRIMARY_PACK_NO = pim.ITEM         THEN 'CONFIGURED TO DISC PACK - UPDATE REQUIRED'         ELSE 'CONFIGURED TO DIFFERENT PACK - VERIFY'     END                                                   AS \"Pack Setup Status\",      ril.PRIMARY_REPL_SUPPLIER                             AS \"Replenishment Supplier ID\",     sp.SUP_NAME                                           AS \"Supplier Name\",      cils.STOCK_ON_HAND                                    AS \"Consumer Current Stock on Hand\",     cils.AV_COST                                          AS \"Consumer Weighted Average Cost\",     cil.SELLING_UNIT_RETAIL                               AS \"Consumer Unit Retail\",     ROUND(cils.STOCK_ON_HAND * cils.AV_COST, 2)          AS \"Consumer Stock on Hand Value\",      pils.STOCK_ON_HAND                                    AS \"Pack Current Stock on Hand\",      CASE         WHEN ril.PRIMARY_PACK_NO IS NULL              AND ril.REPL_METHOD IS NOT NULL         THEN 'HIGH - Consumer replenishing at unit level, pack just discontinued'         WHEN ril.PRIMARY_PACK_NO = pim.ITEM         THEN 'CRITICAL - Primary repl pack is the discontinued pack'         ELSE 'MEDIUM - Review pack configuration'     END                                                   AS \"Risk Level\",      CASE         WHEN ril.PRIMARY_PACK_NO IS NULL         THEN 'Assign alternative simple pack as Primary Pack on REPL_ITEM_LOC'         WHEN ril.PRIMARY_PACK_NO = pim.ITEM         THEN 'Remove discontinued pack from PRIMARY_PACK_NO and assign active replacement'         ELSE 'Verify current PRIMARY_PACK_NO is active and valid for this supplier'     END                                                   AS \"Recommended Action\"  FROM     MFCS_RDS.RDS_WV_ITEM_MASTER             pim      JOIN  MFCS_RDS.RDS_WV_PACKITEM          pi    ON  pim.ITEM        = pi.PACK_NO      JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER       cim   ON  pi.ITEM         = cim.ITEM      JOIN  MFCS_RDS.RDS_WV_DEPS              d     ON  cim.DEPT        = d.DEPT     JOIN  MFCS_RDS.RDS_WV_CLASS             c     ON  cim.DEPT        = c.DEPT                                                   AND  cim.CLASS       = c.CLASS     JOIN  MFCS_RDS.RDS_WV_SUBCLASS          sc    ON  cim.DEPT        = sc.DEPT                                                   AND  cim.CLASS       = sc.CLASS                                                   AND  cim.SUBCLASS    = sc.SUBCLASS      JOIN  MFCS_RDS.RDS_WV_ITEM_LOC          pil   ON  pim.ITEM        = pil.ITEM                                                   AND  pil.STATUS      = 'C'                                                   AND  TRUNC(pil.STATUS_UPDATE_DATE)                                                        &gt;= TRUNC(SYSDATE) - 7      JOIN  MFCS_RDS.RDS_WV_REPL_ITEM_LOC    ril   ON  pi.ITEM          = ril.ITEM                                                   AND  pil.LOC          = ril.LOCATION                                                   AND  ril.REPL_METHOD IS NOT NULL                                                   AND  (                                                        ril.PRIMARY_PACK_NO IS NULL                                                        OR ril.PRIMARY_PACK_NO != pim.ITEM                                                   )      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC      cil   ON  pi.ITEM         = cil.ITEM                                                   AND  pil.LOC         = cil.LOC                                                   AND  pil.LOC_TYPE    = cil.LOC_TYPE      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH  cils  ON  pi.ITEM         = cils.ITEM                                                   AND  pil.LOC         = cils.LOC                                                   AND  pil.LOC_TYPE    = cils.LOC_TYPE      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH  pils  ON  pim.ITEM        = pils.ITEM                                                   AND  pil.LOC         = pils.LOC                                                   AND  pil.LOC_TYPE    = pils.LOC_TYPE      LEFT JOIN MFCS_RDS.RDS_WV_STORE          st   ON  pil.LOC         = st.STORE                                                   AND  pil.LOC_TYPE    = 'S'     LEFT JOIN MFCS_RDS.RDS_WV_WH             wh   ON  pil.LOC         = wh.WH                                                   AND  pil.LOC_TYPE    = 'W'      LEFT JOIN MFCS_RDS.RDS_WV_SUPS           sp   ON  ril.PRIMARY_REPL_SUPPLIER = sp.SUPPLIER  WHERE     pim.PACK_IND = 'Y'  ORDER BY     CASE         WHEN ril.PRIMARY_PACK_NO IS NULL AND ril.REPL_METHOD IS NOT NULL         THEN 'HIGH - Consumer replenishing at unit level, pack just discontinued'         WHEN ril.PRIMARY_PACK_NO = pim.ITEM         THEN 'CRITICAL - Primary repl pack is the discontinued pack'         ELSE 'MEDIUM - Review pack configuration'     END,     TRUNC(SYSDATE) - TRUNC(pil.STATUS_UPDATE_DATE),     d.DEPT_NAME,     cim.ITEM_DESC,     CASE pil.LOC_TYPE WHEN 'S' THEN st.STORE_NAME WHEN 'W' THEN wh.WH_NAME END</ds:dbquery><ds:target_type>Oracle 12c</ds:target_type><ds:object_name/></ds:dataptr><ds:columns><ds:column><ds:name>Report Date</ds:name><ds:datatype>timestamp</ds:datatype></ds:column><ds:column><ds:name>Days Since Discontinued</ds:name><ds:datatype>number</ds:datatype></ds:column><ds:column><ds:name>Department Number</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Department Name</ds:name><ds:datatype>varchar(120)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Class Number</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Class Name</ds:name><ds:datatype>varchar(120)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Subclass Number</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Subclass Name</ds:name><ds:datatype>varchar(120)</ds:datatype><ds:nullable>false</ds:n