itMode\":1,\"filterbarSettings\":{},\"uiSqlStatement\":\"

-- ── Query 2 ────────────────────────────────────────────────────────────
SELECT\\n    TRUNC(SYSDATE)                                        AS \\\"Report Date\\\",\\n    TRUNC(SYSDATE) - TRUNC(pil.STATUS_UPDATE_DATE)       AS \\\"Days Since Discontinued\\\",\\n\\n    cim.DEPT                                              AS \\\"Department Number\\\",\\n    d.DEPT_NAME                                           AS \\\"Department Name\\\",\\n    cim.CLASS                                             AS \\\"Class Number\\\",\\n    c.CLASS_NAME                                          AS \\\"Class Name\\\",\\n    cim.SUBCLASS                                          AS \\\"Subclass Number\\\",\\n    sc.SUB_NAME                                           AS \\\"Subclass Name\\\",\\n\\n    pi.ITEM                                               AS \\\"Consumer Item ID\\\",\\n    cim.ITEM_DESC                                         AS \\\"Consumer Item Description\\\",\\n    cim.STANDARD_UOM                                      AS \\\"Consumer Unit of Measure\\\",\\n    cim.STATUS                                            AS \\\"Consumer Item Status\\\",\\n\\n    pim.ITEM                                              AS \\\"Pack Item ID\\\",\\n    pim.ITEM_DESC                                         AS \\\"Pack Item Description\\\",\\n    pim.PACK_IND                                          AS \\\"Pack Indicator\\\",\\n    pi.PACK_QTY                                           AS \\\"Component Quantity in Pack\\\",\\n\\n    pil.STATUS                                            AS \\\"Pack Location Status\\\",\\n    'Discontinued'                                        AS \\\"Pack Location Status Description\\\",\\n    pil.STATUS_UPDATE_DATE                                AS \\\"Pack Discontinued Date\\\",\\n\\n    pil.LOC                                               AS \\\"Location ID\\\",\\n    pil.LOC_TYPE                                          AS \\\"Location Type\\\",\\n    CASE pil.LOC_TYPE\\n        WHEN 'S' THEN 'Store'\\n        WHEN 'W' THEN 'Warehouse'\\n    END                                                   AS \\\"Location Type Description\\\",\\n    CASE pil.LOC_TYPE\\n        WHEN 'S' THEN st.STORE_NAME\\n        WHEN 'W' THEN wh.WH_NAME\\n    END                                                   AS \\\"Location Name\\\",\\n\\n    cil.STATUS                                            AS \\\"Consumer Location Status\\\",\\n    CASE cil.STATUS\\n        WHEN 'A' THEN 'Active'\\n        WHEN 'C' THEN 'Discontinued'\\n        WHEN 'I' THEN 'Inactive'\\n        WHEN 'D' THEN 'Delete'\\n    END                                                   AS \\\"Consumer Location Status Description\\\",\\n\\n    ril.REPL_METHOD                                       AS \\\"Replenishment Method\\\",\\n    CASE ril.REPL_METHOD\\n        WHEN 'C'  THEN 'Constant'\\n        WHEN 'D'  THEN 'Dynamic'\\n        WHEN 'F'  THEN 'Floating Point'\\n        WHEN 'M'  THEN 'Min/Max'\\n        WHEN 'T'  THEN 'Time Supply'\\n        WHEN 'SO' THEN 'Store Orders'\\n        WHEN 'DI' THEN 'Dynamic - Issues'\\n        WHEN 'S'  THEN 'Dynamic - Seasonal'\\n        WHEN 'TI' THEN 'Time Supply - Issues'\\n        WHEN 'E'  THEN 'Time Supply - Seasonal'\\n        ELSE ril.REPL_METHOD\\n    END                                                   AS \\\"Replenishment Method Description\\\",\\n    ril.STOCK_CAT                                         AS \\\"Stock Category\\\",\\n    CASE ril.STOCK_CAT\\n        WHEN 'C' THEN 'Cross-Docked'\\n        WHEN 'D' THEN 'Direct to Store'\\n        WHEN 'L' THEN 'WH/Cross Link'\\n        WHEN 'W' THEN 'Warehouse Stocked'\\n        WHEN 'X' THEN 'PO Cross-link'\\n        ELSE ril.STOCK_CAT\\n    END                                                   AS \\\"Stock Category Description\\\",\\n    ril.REPL_ORDER_CTRL                                   AS \\\"Order Control\\\",\\n    ril.MIN_STOCK                                         AS \\\"Minimum Stock\\\",\\n    ril.MAX_STOCK                                         AS \\\"Maximum Stock\\\",\\n\\n    ril.PRIMARY_PACK_NO                                   AS \\\"Current Primary Replenishment Pack\\\",\\n    CASE\\n        WHEN ril.PRIMARY_PACK_NO IS NULL\\n        THEN 'NO PACK CONFIGURED - ORDERING AT UNIT LEVEL'\\n        WHEN ril.PRIMARY_PACK_NO = pim.ITEM\\n        THEN 'CONFIGURED TO DISC PACK - UPDATE REQUIRED'\\n        ELSE 'CONFIGURED TO DIFFERENT PACK - VERIFY'\\n    END                                                   AS \\\"Pack Setup Status\\\",\\n\\n    ril.PRIMARY_REPL_SUPPLIER                             AS \\\"Replenishment Supplier ID\\\",\\n    sp.SUP_NAME                                           AS \\\"Supplier Name\\\",\\n\\n    cils.STOCK_ON_HAND                                    AS \\\"Consumer Current Stock on Hand\\\",\\n    cils.AV_COST                                          AS \\\"Consumer Weighted Average Cost\\\",\\n    cil.SELLING_UNIT_RETAIL                               AS \\\"Consumer Unit Retail\\\",\\n    ROUND(cils.STOCK_ON_HAND * cils.AV_COST, 2)          AS \\\"Consumer Stock on Hand Value\\\",\\n\\n    pils.STOCK_ON_HAND                                    AS \\\"Pack Current Stock on Hand\\\",\\n\\n    CASE\\n        WHEN ril.PRIMARY_PACK_NO IS NULL\\n             AND ril.REPL_METHOD IS NOT NULL\\n        THEN 'HIGH - Consumer replenishing at unit level, pack just discontinued'\\n        WHEN ril.PRIMARY_PACK_NO = pim.ITEM\\n        THEN 'CRITICAL - Primary repl pack is the discontinued pack'\\n        ELSE 'MEDIUM - Review pack configuration'\\n    END                                                   AS \\\"Risk Level\\\",\\n\\n    CASE\\n        WHEN ril.PRIMARY_PACK_NO IS NULL\\n        THEN 'Assign alternative simple pack as Primary Pack on REPL_ITEM_LOC'\\n        WHEN ril.PRIMARY_PACK_NO = pim.ITEM\\n        THEN 'Remove discontinued pack from PRIMARY_PACK_NO and assign active replacement'\\n        ELSE 'Verify current PRIMARY_PACK_NO is active and valid for this supplier'\\n    END                                                   AS \\\"Recommended Action\\\"\\n\\nFROM\\n    MFCS_RDS.RDS_WV_ITEM_MASTER             pim\\n\\n    JOIN  MFCS_RDS.RDS_WV_PACKITEM          pi    ON  pim.ITEM        = pi.PACK_NO\\n\\n    JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER       cim   ON  pi.ITEM         = cim.ITEM\\n\\n    JOIN  MFCS_RDS.RDS_WV_DEPS              d     ON  cim.DEPT        = d.DEPT\\n    JOIN  MFCS_RDS.RDS_WV_CLASS             c     ON  cim.DEPT        = c.DEPT\\n                                                  AND  cim.CLASS       = c.CLASS\\n    JOIN  MFCS_RDS.RDS_WV_SUBCLASS          sc    ON  cim.DEPT        = sc.DEPT\\n                                                  AND  cim.CLASS       = sc.CLASS\\n                                                  AND  cim.SUBCLASS    = sc.SUBCLASS\\n\\n    JOIN  MFCS_RDS.RDS_WV_ITEM_LOC          pil   ON  pim.ITEM        = pil.ITEM\\n                                                  AND  pil.STATUS      = 'C'\\n                                                  AND  TRUNC(pil.STATUS_UPDATE_DATE)\\n                                                       &gt;= TRUNC(SYSDATE) - 7\\n\\n    JOIN  MFCS_RDS.RDS_WV_REPL_ITEM_LOC    ril   ON  pi.ITEM          = ril.ITEM\\n                                                  AND  pil.LOC          = ril.LOCATION\\n                                                  AND  ril.REPL_METHOD IS NOT NULL\\n                                                  AND  (\\n                                                       ril.PRIMARY_PACK_NO IS NULL\\n                                                       OR ril.PRIMARY_PACK_NO != pim.ITEM\\n                                                  )\\n\\n    LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC      cil   ON  pi.ITEM         = cil.ITEM\\n                                                  AND  pil.LOC         = cil.LOC\\n                                                  AND  pil.LOC_TYPE    = cil.LOC_TYPE\\n\\n    LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH  cils  ON  pi.ITEM         = cils.ITEM\\n                                                  AND  pil.LOC         = cils.LOC\\n                                                  AND  pil.LOC_TYPE    = cils.LOC_TYPE\\n\\n    LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH  pils  ON  pim.ITEM        = pils.ITEM\\n                                                  AND  pil.LOC         = pils.LOC\\n                                                  AND  pil.LOC_TYPE    = pils.LOC_TYPE\\n\\n    LEFT JOIN MFCS_RDS.RDS_WV_STORE          st   ON  pil.LOC         = st.STORE\\n                                                  AND  pil.LOC_TYPE    = 'S'\\n    LEFT JOIN MFCS_RDS.RDS_WV_WH             wh   ON  pil.LOC         = wh.WH\\n                                                  AND  pil.LOC_TYPE    = 'W'\\n\\n    LEFT JOIN MFCS_RDS.RDS_WV_SUPS           sp   ON  ril.PRIMARY_REPL_SUPPLIER = sp.SUPPLIER\\n\\nWHERE\\n    pim.PACK_IND = 'Y'\\n\\nORDER BY\\n    CASE\\n        WHEN ril.PRIMARY_PACK_NO IS NULL AND ril.REPL_METHOD IS NOT NULL\\n        THEN 'HIGH - Consumer replenishing at unit level, pack just discontinued'\\n        WHEN ril.PRIMARY_PACK_NO = pim.ITEM\\n        THEN 'CRITICAL - Primary repl pack is the discontinued pack'\\n        ELSE 'MEDIUM - Review pack configuration'\\n    END,\\n    TRUNC(SYSDATE) - TRUNC(pil.STATUS_UPDATE_DATE),\\n    d.DEPT_NAME,\\n    cim.ITEM_DESC,\\n    CASE pil.LOC_TYPE WHEN 'S' THEN st.STORE_NAME WHEN 'W' THEN wh.WH_NAME END;\"},\"editorCurrentState\":false,\"joins\":{\"tables\":[]}}</ds:uiOptions><ds:version>v5</ds:version></ds:datasetImportOptions>","business-model":"\"\"","active":true,"custom-attrs":"{\"src_parquet_verified\":\"true\"}","description":"External dataset","display-name":"Manual Query","locale":"sys","is-user-striped":false,"file-length":0,"type":"sql","properties-last-modified":"2026-07-14T01:39:25.715+0000","connection-namespace":"disadmin_disadmin_APPID","private-connection":false,"credential-exists":true,"connection-name":"Remote RDS MFCS Connection","provider-type":"db","provider-name":"oracle","sso-enabled":false,"datamodelname":"'ReCommon'.'RPT_062_ReplPack_discontinue7days'","parent-namespace":"ReCommon","parent-name":"RPT_062_ReplPack_discontinue7days","data-access-mode":"auto","is-data-cacheable":true,"checkpoint-metadata-stale":false,"owner-guid":"ReCommon","is-temporary":false},"datasetType":"EMBEDDED","datamodelTwoPartName":"'ReCommon'.'RPT_062_ReplPack_discontinue7days'"}
